INSERT INTO rules(id,raw_id,name,description,severity,category_id,enabled,is_abstract,triggers,updated_at)
VALUES (?1,?2,?3,?4,?5,?6, COALESCE((SELECT enabled FROM rules WHERE id=?1), ?7), 0, ?8, strftime('%Y-%m-%dT%H:%M:%fZ','now'))
ON CONFLICT(id) DO UPDATE SET name=excluded.name, description=excluded.description, severity=excluded.severity, category_id=excluded.category_id, triggers=excluded.triggers, updated_at=excluded.updated_at;
